CREATE TABLE vermietung_vorlagenimport (
 id VARCHAR(36) PRIMARY KEY, benutzer VARCHAR(255) NOT NULL, tenant VARCHAR(255) NOT NULL,
 ablauf TIMESTAMP WITH TIME ZONE NOT NULL, paket BYTEA, paket_hash VARCHAR(64) NOT NULL,
 plan TEXT, ziel_hash VARCHAR(64), geprueft BOOLEAN NOT NULL DEFAULT FALSE, uebernommen BOOLEAN NOT NULL DEFAULT FALSE
);
CREATE INDEX ix_vorlagenimport_ablauf ON vermietung_vorlagenimport(ablauf);
